#include <iostream>
#include <queue>
using namespace std;

int main() {
    int n, m;
    if (!(cin >> n >> m)) return 0;
    queue<int> q;
    for (int i = 1; i <= n; i++) q.push(i);

    bool first = true;
    while (!q.empty()) {
        for (int i = 1; i < m; i++) {   // 前 m-1 个人移到队尾
            q.push(q.front());
            q.pop();
        }
        if (!first) cout << ' ';
        cout << q.front();              // 第 m 个人出列
        q.pop();
        first = false;
    }
    cout << "\n";
    return 0;
}
